import{_ as e,o as a,c as o,a2 as d}from"./chunks/framework.C9_66ieh.js";const u=JSON.parse('{"title":"Tasks & launch (MCP-first)","description":"","frontmatter":{},"headers":[],"relativePath":"task-board.md","filePath":"task-board.md","lastUpdated":1785285564000}'),s={name:"task-board.md"};function r(n,t,i,c,l,h){return a(),o("div",null,[...t[0]||(t[0]=[d(`<h1 id="tasks-launch-mcp-first" tabindex="-1">Tasks &amp; launch (MCP-first) <a class="header-anchor" href="#tasks-launch-mcp-first" aria-label="Permalink to &quot;Tasks &amp; launch (MCP-first)&quot;">​</a></h1><p>Tasks dispatch real agent CLI sessions. There is <strong>no board UI panel</strong> - agents (and you) use <strong>TrueDeck MCP hub</strong> tools.</p><h2 id="primary-flow" tabindex="-1">Primary flow <a class="header-anchor" href="#primary-flow" aria-label="Permalink to &quot;Primary flow&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>truedeck_launch({ title, body?, agentId?, roleId?, isolate? })</span></span>
<span class="line"><span> → queue → Electron createTask + dispatchTask → live PTY tab</span></span></code></pre></div><p>TrueDeck must be running. See <a href="./mcp">MCP</a>.</p><h2 id="columns-statuses" tabindex="-1">Columns / statuses <a class="header-anchor" href="#columns-statuses" aria-label="Permalink to &quot;Columns / statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Meaning</th></tr></thead><tbody><tr><td><code>backlog</code></td><td>Captured, not ready</td></tr><tr><td><code>ready</code></td><td>Ready to run</td></tr><tr><td><code>running</code></td><td>Agent session attached</td></tr><tr><td><code>review</code></td><td>Session exited; human reviews outcome</td></tr><tr><td><code>done</code></td><td>Finished</td></tr><tr><td><code>blocked</code></td><td>Stuck / failed path</td></tr></tbody></table><p>Types: <code>TaskStatus</code> in <code>electron/shared/types.ts</code>.</p><h2 id="task-model" tabindex="-1">Task model <a class="header-anchor" href="#task-model" aria-label="Permalink to &quot;Task model&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>UUID</td></tr><tr><td><code>projectRoot</code></td><td>Owning project path</td></tr><tr><td><code>title</code> / <code>body</code></td><td>Human-readable work</td></tr><tr><td><code>status</code></td><td>Kanban column</td></tr><tr><td><code>assigneeAgentId</code></td><td>e.g. <code>claude</code>, <code>codex</code>, <code>grok</code>, <code>cursor</code>, <code>shell</code></td></tr><tr><td><code>sessionId</code></td><td>Live PTY session when running</td></tr><tr><td><code>runIds</code></td><td>Agent run history</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>Epoch ms</td></tr></tbody></table><p>Store file (app data): <code>tasks.json</code> under the global data directory. Command queue: <code>deck-command-queue.json</code> (MCP → Electron).</p><p>Without a project, the board shows a hint to open a folder first.</p><h2 id="dispatch-pipeline" tabindex="-1">Dispatch pipeline <a class="header-anchor" href="#dispatch-pipeline" aria-label="Permalink to &quot;Dispatch pipeline&quot;">​</a></h2><p><code>electron/main/task-dispatch.ts</code> → <code>dispatchTask(taskId, agentIdOverride?)</code>:</p><ol><li>Load task; resolve agent preset (default <code>shell</code> if unassigned)</li><li><strong>Write task file</strong> under the repo:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;projectRoot&gt;/.truedeck/tasks/&lt;first-8-of-uuid&gt;.md</span></span></code></pre></div><p>Markdown includes title, status, agent, instructions body, and a short TrueDeck footer (summarize when done; board moves to <strong>Review</strong> on session exit).</p><ol start="3"><li><strong>Write focus file</strong> for the agent-frame header:</li></ol><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;projectRoot&gt;/.truedeck/current-focus.md</span></span></code></pre></div><ol start="4"><li>Build env via <code>onAgentSpawnFast</code> plus:</li></ol><table tabindex="0"><thead><tr><th>Env</th><th>Content</th></tr></thead><tbody><tr><td><code>TRUEDECK_TASK</code></td><td>Full task id</td></tr><tr><td><code>TRUEDECK_TASK_FILE</code></td><td>Absolute path to task <code>.md</code></td></tr><tr><td><code>TRUEDECK_TASK_TITLE</code></td><td>Title (≤ 80 chars)</td></tr><tr><td><code>TRUEDECK_TASK_IDEA</code></td><td>Title + first sentence of body (≤ 160 chars)</td></tr></tbody></table><ol start="5"><li><code>ptyManager.spawn</code> with <code>extraEnv</code></li><li><code>startRun</code> + attach run to task; status → <code>running</code></li><li>After ~<strong>1200 ms</strong>, best-effort write a seed prompt into the PTY (Windows uses <code>\\r</code> line endings)</li></ol><p>Seed text points the agent at the relative task file and asks for durable notes under <code>.memory/</code> when relevant.</p><h2 id="on-session-exit" tabindex="-1">On session exit <a class="header-anchor" href="#on-session-exit" aria-label="Permalink to &quot;On session exit&quot;">​</a></h2><p><code>tasks.onSessionExit(sessionId, exitCode)</code> moves a linked <code>running</code> task toward <strong>review</strong> (or blocked depending on exit handling). Check <code>tasks.ts</code> for exact exit mapping.</p><h2 id="project-files-in-repo" tabindex="-1">Project files (in-repo) <a class="header-anchor" href="#project-files-in-repo" aria-label="Permalink to &quot;Project files (in-repo)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Role</th></tr></thead><tbody><tr><td><code>.truedeck/tasks/*.md</code></td><td>Per-task instructions for agents</td></tr><tr><td><code>.truedeck/current-focus.md</code></td><td>One-line “main idea” for <a href="./agent-frame">agent frame</a></td></tr><tr><td><code>.truedeck/auto-context.md</code></td><td>Session memory auto-context (related, not board-only)</td></tr></tbody></table><p>These are safe to commit or gitignore depending on your team’s preference. TrueDeck recreates them on dispatch / project open as needed.</p><h2 id="mcp-task-tools" tabindex="-1">MCP task tools <a class="header-anchor" href="#mcp-task-tools" aria-label="Permalink to &quot;MCP task tools&quot;">​</a></h2><p>Agents with the TrueDeck hub MCP can manage the shared store:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Purpose</th></tr></thead><tbody><tr><td><code>truedeck_list_tasks</code></td><td>List tasks (<code>projectRoot</code> when set)</td></tr><tr><td><code>truedeck_create_task</code></td><td>Create card (does not auto-dispatch a PTY)</td></tr><tr><td><code>truedeck_update_task</code></td><td>Patch title/body/status/assignee</td></tr></tbody></table><p>Creating a task via MCP does <strong>not</strong> spawn an agent; the human still uses Run/dispatch in TrueDeck for a live PTY. See <a href="./mcp">MCP</a>.</p><h2 id="worktree-isolation" tabindex="-1">Worktree isolation <a class="header-anchor" href="#worktree-isolation" aria-label="Permalink to &quot;Worktree isolation&quot;">​</a></h2><p><code>AppSettings.worktreeIsolationDefault</code> exists for future git worktree isolation on dispatch (default <strong>false</strong> / not required for board use today).</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./agents">Agents</a> - spawn and resolve</li><li><a href="./agent-frame">Agent frame</a> - idea line sources</li><li><a href="./user-guide">User guide</a></li></ul>`,36)])])}const k=e(s,[["render",r]]);export{u as __pageData,k as default};
